<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class EditRequest extends Model { public const MONTHLY_LIMIT=3; public const TYPES=['clock_in','forgot_break_start','forgot_break_end','clock_tower_not_working']; protected $fillable=['user_id','time_clock_id','requested_clock_in','requested_break_in','requested_break_out','reason','status','manager_note','resolved_at','department','approved_by_manager','approved_by_admin','manager_approved_by','admin_approved_by','request_type','break_reason']; protected function casts():array{return ['requested_clock_in'=>'datetime','requested_break_in'=>'datetime','requested_break_out'=>'datetime','resolved_at'=>'datetime','approved_by_manager'=>'boolean','approved_by_admin'=>'boolean'];} public function user(){return $this->belongsTo(User::class);} public function timeClock(){return $this->belongsTo(TimeClock::class);} public function histories(){return $this->morphMany(ApprovalHistory::class,'approvable');} public function managerActionable():bool{return $this->created_at?->gte(now()->subWeek())??true;} }
